INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 4, 'theory', 'Quiz: logs');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 0, 'What decides whether the journald journal survives a reboot when Storage=auto?', '["The value of SystemMaxUse", "Whether rsyslog is installed", "Whether the directory /var/log/journal exists", "The amount of RAM"]', 2, 'With auto the journal is persistent only if /var/log/journal exists; otherwise records stay in /run/log/journal and vanish at reboot.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 1, 'What does the selector *.*;auth,authpriv.none do in an rsyslog rule?', '["Selects only auth and authpriv messages", "Selects all messages except the auth and authpriv facilities", "Selects messages with the priority none", "Disables the whole rule"]', 1, 'Selectors apply left to right: *.* selects everything and auth,authpriv.none subtracts those two facilities.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 2, 'Which facility and priority does a message with the PRI number 38 carry?', '["user, debug", "mail, notice", "kern, err", "auth, info"]', 3, '38 = 4 × 8 + 6: facility 4 is auth and priority 6 is info.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 3, 'What does delaycompress do together with compress?', '["Compression of the previous copy is postponed to the next rotation", "The file is compressed before rotation", "Uncompressed copies are deleted at once", "Only empty files are compressed"]', 0, 'The newest copy stays uncompressed while a program may still write to it; it is compressed on the next cycle.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 4, 'What is deleted when the journal runs out of room because of SystemMaxUse or SystemKeepFree?', '["The active journal file", "The newest records", "Only archived files, oldest first", "All files older than a day"]', 2, 'The journal deletes only archived files, oldest first, and leaves the active file alone. journalctl --vacuum-size does the same by hand.');
